/* a tachometer dial (needle near the top of the scale), centred at x,y */
function AE_tach(x,y){const r=100,arc=[];for(let a=210;a>=-30;a-=6)arc.push([x+r*Math.cos(a*Math.PI/180),y-r*Math.sin(a*Math.PI/180)]);
 const ticks=[210,170,130,90,50,10,-30].map(a=>AE_L(x+(r-14)*Math.cos(a*Math.PI/180),y-(r-14)*Math.sin(a*Math.PI/180),x+r*Math.cos(a*Math.PI/180),y-r*Math.sin(a*Math.PI/180),AE_DARK,3)).join('');
 const na=10*Math.PI/180;
 return `<circle cx="${x}" cy="${y}" r="${r+12}" fill="#FFFFFF" stroke="${AE_DARK}" stroke-width="3"/>${AE_PL(arc,AE_DARK,4)}${ticks}${AE_L(x,y,x+(r-22)*Math.cos(na),y-(r-22)*Math.sin(na),RED,5)}<circle cx="${x}" cy="${y}" r="9" fill="${AE_DARK}"/>${AE_T(x,y+52,'engine rpm ↑',{fs:22,fw:800,a:'middle',fill:AE_GREY})}`}
/* axes for a small output-current plot: origin x0,y0, width w, height h */
function AE_axes(x0,y0,w,h){return AE_L(x0,y0,x0+w,y0,AE_GREY,2.5)+AE_L(x0,y0,x0,y0-h,AE_GREY,2.5)+AE_T(x0+w,y0+26,'speed',{fs:22,fw:600,a:'end',fill:AE_GREY})+AE_T(x0-10,y0-h+6,'I',{fs:24,fw:800,a:'end',fill:AE_GREY})}
/* the three-phase bridge: legs at x 90, 170, 250; top rail (B+) y 40, bottom rail (B−) y 290; hot = [[leg,'up'|'dn']] diodes highlighted */
function AE_bridge(hot,col){const X=[90,170,250];let s=AE_L(90,40,330,40,AE_DARK,3)+AE_L(90,290,330,290,AE_DARK,3)+AE_T(340,48,'B+',{fs:24,fw:800})+AE_T(340,298,'B−',{fs:24,fw:800});
 X.forEach((x,i)=>{const up=hot.some(([l,d])=>l===i&&d==='up'),dn=hot.some(([l,d])=>l===i&&d==='dn');
  s+=AE_L(x,40,x,290,AE_DARK,3)+AE_diode(x,100,up?col:AE_DARK,1.1,up?col:'#FFFFFF')+AE_diode(x,230,dn?col:AE_DARK,1.1,dn?col:'#FFFFFF')+`<circle cx="${x}" cy="165" r="6" fill="${AE_DARK}"/>`+AE_T(x-14,172,'UVW'[i],{fs:22,fw:800,a:'end',fill:AE_GREY})});
 if(hot.length>1)s+=`<path d="M250,165 C230,205 110,205 90,165" fill="none" stroke="${col}" stroke-width="3" stroke-dasharray="7 5"/>`+AE_T(170,214,'stator',{fs:22,a:'middle',fill:col});
 return s}

