 ICON.aeBelt=(x,y)=>`<g transform="translate(${x-200} ${y-95})">${AE_box(0,0,400,190,{fill:'#FFFFFF',st:BLU,sw:3,r:20})}
  <path d="M95,46 L235,62 A30,30 0 0 1 235,122 L95,150 A52,52 0 0 1 95,46 Z" fill="none" stroke="${AE_DARK}" stroke-width="7"/>
  <circle cx="95" cy="98" r="44" fill="${AE_AL}" stroke="${AE_STEEL}" stroke-width="4"/>${AE_T(95,106,'crank',{fs:22,a:'middle',fill:AE_STEEL})}
  <circle cx="235" cy="92" r="26" fill="${AE_AL}" stroke="${AE_STEEL}" stroke-width="4"/><circle cx="235" cy="92" r="8" fill="${AE_STEEL}"/>
  ${AE_T(272,58,'alternator',{fs:22,fw:800,fill:BLU})}${AE_arrow(270,110,330,140,ORG,4)}${AE_T(370,170,'14 V',{fs:26,fw:900,a:'end',fill:ORG})}</g>`;
 /* recap pictures: each fills most of its card (about 420 × 330) */
 ICON.aeRec1=(x,y)=>`<g transform="translate(${x-210} ${y-165})">
  <circle cx="90" cy="120" r="70" fill="#E6E9FB" stroke="#2F3FA8" stroke-width="4"/>${AE_coil(45,130,90,3,AE_CU,4)}${AE_T(90,92,'alternator',{fs:22,fw:800,a:'middle',fill:'#2F3FA8'})}
  ${AE_L(160,120,300,120,'#343A40',8)}${AE_box(300,70,110,110,{fill:'#FFFFFF',st:'#343A40',sw:3})}${AE_batt(345,122)}
  ${AE_box(150,30,140,50,{fill:GRN,st:GRN,r:25})}${AE_T(220,64,'≈ 14 V',{fs:28,fw:900,a:'middle',fill:'#FFFFFF'})}
  ${AE_lamp(210,250,1)}${AE_arrow(180,250,110,200,ORG,4)}${AE_T(260,258,'first field',{fs:22,fw:700,fill:ORG})}${AE_T(260,286,'current',{fs:22,fw:700,fill:ORG})}</g>`;
 ICON.aeRec2=(x,y)=>{const yM=290-144/160*240;return `<g transform="translate(${x-210} ${y-165})">${AE_axes(40,290,360,240)}<line x1="40" y1="${yM.toFixed(1)}" x2="400" y2="${yM.toFixed(1)}" stroke="${ORG}" stroke-width="2.5" stroke-dasharray="8 6"/>${AE_T(398,yM-10,'I<tspan baseline-shift="sub" font-size="70%">max</tspan>',{fs:24,fw:800,a:'end',fill:ORG})}${AE_PL(AE_curve(40,290,360,240),BLU,5)}${AE_T(60,284,'cut-in',{fs:22,fw:700,fill:AE_GREY})}</g>`};
 ICON.aeRec3=(x,y)=>{const W=400,o=980/1300*W;return `<g transform="translate(${x-210} ${y-165})">${AE_T(10,30,'1300 W in',{fs:24,fw:800})}<rect x="10" y="44" width="${o.toFixed(1)}" height="64" rx="6" fill="#E6E9FB" stroke="#2F3FA8" stroke-width="3"/><rect x="${(10+o).toFixed(1)}" y="44" width="${(W-o).toFixed(1)}" height="64" rx="6" fill="#FFE8CC" stroke="${ORG}" stroke-width="3"/>
  ${AE_T(10+o/2,86,'980 W out',{fs:24,fw:800,a:'middle',fill:'#2F3FA8'})}${AE_T(10+o+(W-o)/2,140,'320 W',{fs:22,fw:800,a:'middle',fill:ORG})}${AE_heat(10+o+(W-o)/2,40)}
  ${AE_L(10,300,410,300,'#ADB5BD',2)}${AE_PL(AE_pwm(10,300,200,100,[.857,.857,.857,.857]),PUR,4)}${AE_T(210,186,'field on 85.7 %',{fs:22,fw:800,a:'middle',fill:PUR})}</g>`};
